new='''// Rejoins c-new, sends the frames, and once each is answered sends a ping, whose pong shows nothing further was sent.
const exchange = async (base: string, sent: object[]): Promise<{frames: Frame[]; client: WebSocket}> => {
  const client = new WebSocket(`${base}?sessionId=c-new`, [HAL_WS_SUBPROTOCOL, 't']);
  clients.push(client);
  const frames: Frame[] = [];
  let answered = 0;
  const barrier = () => client.send(JSON.stringify({type: 'ping', timestamp: 1}));
  await new Promise<void>(resolve => {
    // An answer that never comes still settles, so its absence fails the assertion instead of the timeout.
    const fallback = setTimeout(barrier, 1500);
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      frames.push(frame);
      if (frame.type === 'connected') for (const message of sent) client.send(JSON.stringify(message));
      if (['conversation_list', 'error'].includes(frame.type) && ++answered === sent.length) {
        clearTimeout(fallback);
        barrier();
      }
      if (frame.type === 'pong') resolve();
    });
  });
  return {frames, client};
};

